// and in many a pillager bag beside the gun in his hands. After the build, every gun in a container or in a pillager bag is kept
// with a chance of GUN_KEEP (0.4) and otherwise becomes a valuable of the same rarity (GUN_SWAP), so a box holds as many things as
// before and roughly what they were worth, just far fewer guns. A man still carries and drops the gun in his hands. It runs on its
// own side stream (GUN_TAG), so the seeded stream, the ents and the containers are what they were, and the same seed thins the same
// guns on both windows of a co-op raid. The bot raid is not thinned. G.gunThin keeps the count before and after.
var GUN_KEEP=0.4, GUN_TAG=49, GUN_SWAP={common:'wire',uncommon:'servo',rare:'core',elite:'codex',gold:'codex'};
function gunThin(g){
  var n0=0, n1=0;
  if(!g||g.sim) return;
  sideStream(g.seed,GUN_TAG,function(){
    var i, j, c, L, k, it, own, e;
    function thin(arr,keep){
      for(j=0;j<arr.length;j++){
        k=arr[j]; it=ITEMS[k]; if(!it||it.use!=='gun') continue;
        if(keep&&k===keep){ keep=null; continue; }
        n0++;
        if(rr()<GUN_KEEP){ n1++; continue; }
        arr[j]=GUN_SWAP[dispR(k)]||'core';
      }
    }
